PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    PumpInTimer : TON;
    ValveOutTimer : TON;
    LowLimit : INT := 10;
    HighLimit : INT := 90;
END_VAR

PumpInTimer(IN := PumpIn, PT := T#5s);
ValveOutTimer(IN := ValveOut, PT := T#5s);

IF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : CONST INT := 10;
    HighLimit : CONST INT := 90;
    PumpTimer : TON;
END_VAR

// Check if the level is below the low limit and turn on the pump
IF Level <= LowLimit THEN
    PumpIn := TRUE;
    PumpTimer(IN := TRUE, PT := T#1s);
ELSE
    PumpIn := FALSE;
END_IF;

// Check if the level is above the high limit and turn on the valve
IF Level >= HighLimit THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

// Ensure the pump does not run when the level is above the high limit
IF Level > HighLimit AND PumpIn THEN
    PumpIn := FALSE;
END_IF;

// Reset the pump timer if the level is within the safe range
IF Level > LowLimit AND Level < HighLimit THEN
    PumpTimer(IN := FALSE);
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prevLevel : INT := 0;
    highLimit : INT := 90;
    lowLimit : INT := 10;
    hysteresis : INT := 5;
END_VAR

// Check if the level is within the safe operating range
IF Level >= highLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= lowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Hysteresis logic
IF (Level <= lowLimit + hysteresis) AND (prevLevel > lowLimit + hysteresis) THEN
    PumpIn := TRUE;
END_IF;
IF (Level >= highLimit - hysteresis) AND (prevLevel < highLimit - hysteresis) THEN
    PumpIn := FALSE;
END_IF;

prevLevel := Level;
END_PROGRAM

