        DoorA_Timer(IN := FALSE, PT := T#0s);
    END_IF;
END_IF;

IF OpenB_Cmd THEN
    IF NOT DoorA_Open THEN
        DoorB := TRUE;
        DoorB_Timer(IN := TRUE, PT := T#0s);
    ELSE
        DoorB := FALSE;
    END_IF;
ELSE
    IF DoorB_Timer.Q THEN
        DoorB := FALSE;
        DoorB_Timer(IN := FALSE, PT := T#0s);
    END_IF;
END_IF;

