PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    DoorA_Open : BOOL := FALSE;
    DoorB_Open : BOOL := FALSE;
    T_A_to_B : TON;
    T_B_to_A : TON;
END_VAR

// Update the states based on commands and current status
IF OpenA_Cmd THEN
    IF NOT DoorB THEN
        DoorA := TRUE;
        DoorB := FALSE;
        T_A_to_B(IN := TRUE, PT := T#0s);
        T_B_to_A(IN := FALSE, PT := T#0s);
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
        T_A_to_B(IN := FALSE, PT := T#0s);
        T_B_to_A(IN := FALSE, PT := T#0s);
    END_IF;
ELSIF OpenB_Cmd THEN
    IF NOT DoorA THEN
        DoorA := FALSE;
        DoorB := TRUE;
        T_A_to_B(IN := FALSE, PT := T#0s);
        T_B_to_A(IN := TRUE, PT := T#0s);
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
        T_A_to_B(IN := FALSE, PT := T#0s);
        T_B_to_A(IN := FALSE, PT := T#0s);
    END_IF;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
    T_A_to_B(IN := FALSE, PT := T#0s);
    T_B_to_A(IN := FALSE, PT := T#0s);
END_IF;

// Ensure only one door can be open at a time
IF DoorA AND DoorB THEN
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

// Maintain the open state for a short period if necessary
IF T_A_to_B.Q THEN
    DoorA := TRUE;
    DoorB := FALSE;
END_IF;

IF T_B_to_A.Q THEN
    DoorA := FALSE;
    DoorB := TRUE;
END_IF;

END_PROGRAM

