IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
    Latched := FALSE;
ELSIF StartTimer.Q AND NOT Running THEN
    Running := TRUE;
    Latched := TRUE;
END_IF;

Conveyor := Running AND Latched;

