PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL := FALSE;
    GuardTimer : TON;
END_VAR

// Reset the running state if StopPB is pressed, guard opens, or fault occurs
IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
END_IF;

// Start the conveyor if all conditions are met and not already running
IF StartPB AND GuardClosed AND NOT Fault AND NOT Running THEN
    Running := TRUE;
END_IF;

// Assign the running state to the conveyor output
Conveyor := Running;

// Update the guard timer if the guard is closed
IF GuardClosed THEN
    GuardTimer(IN := TRUE, PT := T#5s);
ELSE
    GuardTimer(IN := FALSE);
END_IF;

// Reset the running state if the guard timer expires
IF GuardTimer.Q THEN
    Running := FALSE;
END_IF;

END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    Latched : BOOL := FALSE;
    GuardTimer : TON;
END_VAR

CONSTANT
    GuardDelay : TIME := T#0.5s;
END_CONSTANT

// Reset Latch if Fault or StopPB is pressed
IF Fault OR StopPB THEN
    Latched := FALSE;
END_IF;

// Handle StartPB input
IF StartPB AND NOT Running AND GuardClosed AND NOT Fault THEN
    Running := TRUE;
    Latched := TRUE;
    GuardTimer(IN := TRUE, PT := GuardDelay);
END_IF;

// Handle StopPB input
IF StopPB THEN
    Running := FALSE;
    Latched := FALSE;
END_IF;

// Check for GuardOpen after delay
IF GuardTimer.Q AND GuardClosed = FALSE THEN
    Running := FALSE;
    Latched := FALSE;
END_IF;

// Update Conveyor output
Conveyor := Running AND Latched;
END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    Latched : BOOL := FALSE;
    StopTimer : TON;
END_VAR

CONVEYOR := FALSE;

IF StopPB THEN
    Running := FALSE;
    Latched := FALSE;
END_IF;

IF GuardClosed AND NOT Fault AND StartPB AND NOT Running THEN
    Running := TRUE;
    Latched := TRUE;
END_IF;

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
    Latched := FALSE;
END_IF;

If Running THEN
    Conveyor := TRUE;
END_IF;

END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    Latched : BOOL := FALSE;
    StartTimer : TON;
END_VAR

StartTimer(IN := StartPB AND GuardClosed AND NOT Fault, PT := T#0s);

IF StartTimer.Q THEN
    Running := TRUE;
    Latched := TRUE;
END_IF;

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
    Latched := FALSE;
END_IF;

Conveyor := Running AND Latched;
END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    StartTimer : TON;
END_VAR

StartTimer(IN := StartPB AND GuardClosed AND NOT Fault AND NOT Running, PT := T#0s);

Conveyor := Running OR (StartTimer.Q AND NOT Fault AND GuardClosed);

IF StopPB THEN
    Running := FALSE;
END_IF;

IF NOT GuardClosed THEN
    Running := FALSE;
END_IF;

IF Fault THEN
    Running := FALSE;
END_IF;
END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    ConveyorRunning : BOOL := FALSE;
    ConveyorLatch : BOOL := FALSE;
    StartTimer : TON;
END_VAR

// Initialize timer preset to 0s
StartTimer(IN := FALSE, PT := T#0s);

// Check if conveyor should start
IF StartPB AND GuardClosed AND NOT Fault THEN
    StartTimer(IN := TRUE, PT := T#1s);
    IF StartTimer.Q THEN
        ConveyorRunning := TRUE;
        ConveyorLatch := TRUE;
    END_IF;
END_IF;

// Check if conveyor should stop
IF StopPB OR NOT GuardClosed OR Fault THEN
    ConveyorRunning := FALSE;
    ConveyorLatch := FALSE;
END_IF;

// Set conveyor output based on state
Conveyor := ConveyorRunning AND ConveyorLatch;
END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL := FALSE;
    StartTimer : TON;
END_VAR

StartTimer(IN := StartPB AND GuardClosed AND NOT Fault AND NOT Running, PT := T#0s);

Conveyor := Running;

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
ELSIF StartTimer.Q THEN
    Running := TRUE;
END_IF;

END_PROGRAM

