PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    TNS_G, TEW_G : TON;
    TNS_Y, TEW_Y : TON;
    TNS_AllRed, TEW_AllRed : TON;
END_VAR

State := State MOD 6;

CASE State OF
    0:
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TNS_G(IN := TRUE, PT := T#2s);
        TEW_G(IN := FALSE, PT := T#0s);
        TNS_Y(IN := FALSE, PT := T#0s);
        TEW_Y(IN := FALSE, PT := T#0s);
        TNS_AllRed(IN := FALSE, PT := T#0s);
        TEW_AllRed(IN := FALSE, PT := T#0s);
    1:
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TNS_G(IN := FALSE, PT := T#0s);
        TEW_G(IN := FALSE, PT := T#0s);
        TNS_Y(IN := TRUE, PT := T#1s);
        TEW_Y(IN := FALSE, PT := T#0s);
        TNS_AllRed(IN := FALSE, PT := T#0s);
        TEW_AllRed(IN := FALSE, PT := T#0s);
    2:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TNS_G(IN := FALSE, PT := T#0s);
        TEW_G(IN := FALSE, PT := T#0s);
        TNS_Y(IN := FALSE, PT := T#0s);
        TEW_Y(IN := FALSE, PT := T#0s);
        TNS_AllRed(IN := TRUE, PT := T#1s);
        TEW_AllRed(IN := FALSE, PT := T#0s);
    3:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
        TNS_G(IN := FALSE, PT := T#0s);
        TEW_G(IN := TRUE, PT := T#2s);
        TNS_Y(IN := FALSE, PT := T#0s);
        TEW_Y(IN := FALSE, PT := T#0s);
        TNS_AllRed(IN := FALSE, PT := T#0s);
        TEW_AllRed(IN := FALSE, PT := T#0s);
    4:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
        TNS_G(IN := FALSE, PT := T#0s);
        TEW_G(IN := FALSE, PT := T#0s);
        TNS_Y(IN := FALSE, PT := T#1s);
        TEW_Y(IN := TRUE, PT := T#0s);
        TNS_AllRed(IN := FALSE, PT := T#0s);
        TEW_AllRed(IN := FALSE, PT := T#0s);
    5:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TNS_G(IN := FALSE, PT := T#0s);
        TEW_G(IN := FALSE, PT := T#0s);
        TNS_Y(IN := FALSE, PT := T#0s);
        TEW_Y(IN := FALSE, PT := T#0s);
        TNS_AllRed(IN := TRUE, PT := T#1s);
        TEW_AllRed(IN := FALSE, PT := T#0s);
END_CASE

NS_G := TNS_G.Q AND NOT TEW_G.Q;
NS_Y := TNS_Y.Q AND NOT TEW_Y.Q;
NS_R := TNS_AllRed.Q OR TEW_AllRed.Q;

EW_G := TEW_G.Q AND NOT TNS_G.Q;
EW_Y := TEW_Y.Q AND NOT TNS_Y.Q;
EW_R := TNS_AllRed.Q OR TEW_AllRed.Q;
END_PROGRAM

PROGRAM intersection
VAR
    State : INT := 0;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    T_Green, T_Yellow, T_AllRed : TON;
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

T_Green(IN := State = 0 OR State = 3, PT := PT_GREEN);
T_Yellow(IN := State = 1 OR State = 4, PT := PT_YELLOW);
T_AllRed(IN := State = 2 OR State = 5, PT := PT_ALLRED);

CASE State OF
    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := TRUE;
    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := TRUE;
    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
END_CASE;

IF T_Green.Q AND NOT T_Yellow.Q THEN
    NS_G := TRUE;
    NS_Y := FALSE;
    NS_R := FALSE;
    EW_G := FALSE;
    EW_Y := FALSE;
    EW_R := TRUE;
ELSIF T_Yellow.Q AND NOT T_Green.Q THEN
    NS_G := FALSE;
    NS_Y := TRUE;
    NS_R := FALSE;
    EW_G := FALSE;
    EW_Y := FALSE;
    EW_R := TRUE;
ELSIF T_AllRed.Q AND NOT (T_Green.Q OR T_Yellow.Q) THEN
    NS_G := FALSE;
    NS_Y := FALSE;
    NS_R := TRUE;
    EW_G := FALSE;
    EW_Y := FALSE;
    EW_R := TRUE;
END_IF;

IF (NS_G OR NS_Y) AND (EW_G OR EW_Y) THEN
    // This should not happen in a safe system, but for completeness
    NS_G := FALSE;
    NS_Y := FALSE;
    NS_R := TRUE;
    EW_G := FALSE;
    EW_Y := FALSE;
    EW_R := TRUE;
END_IF;

IF T_Green.Q THEN
    State := 1;
ELSIF T_Yellow.Q THEN
    State := 2;
ELSIF T_AllRed.Q THEN
    IF State = 0 THEN
        State := 3;
    ELSIF State = 1 THEN
        State := 4;
    ELSE
        State := 0;
    END_IF;
END_IF;
END_PROGRAM

PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    TON_NS_G, TON_NS_Y, TON_NS_R, TON_EW_G, TON_EW_Y, TON_EW_R : TON;
