END_VAR

// Assign timer presets in seconds
CONST
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T #1s;
END_CONST

// Main control logic
State := State MOD 6;

CASE State OF
    0: // NS green / EW red
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TNS_G(IN := NS_G, PT := PT_GREEN);
        TEW_G(IN := EW_G, PT := PT_RED);
        TNR(IN := NS_R, PT := PT_ALLRED);
