        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TNS_G(IN := NS_G, PT := PT_YELLOW);
        TEW_G(IN := EW_G, PT := PT_RED);
        TNR(IN := NS_R, PT := PT_ALLRED);
        TWR(IN := EW_R, PT := PT_RED);

    2: // All-red clearance
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TNS_G(IN := NS_G, PT := PT_ALLRED);
        TEW_G(IN := EW_G, PT := PT_ALLRED);
        TNR(IN := NS_R, PT := PT_ALLRED);
        TWR(IN := EW_R, PT := PT_ALLRED);

    3: // EW green / NS red
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;
        TNS_G(IN := NS_G, PT := PT_RED);
        TEW_G(IN := EW_G, PT := PT_GREEN);
        TNR(IN := NS_R, PT := PT_RED);
        TWR(IN := EW_R, PT := PT_ALLRED);

    4: // EW yellow / NS red
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
        TNS_G(IN := NS_G, PT := PT_RED);
        TEW_G(IN := EW_G, PT := PT_YELLOW);
        TNR(IN := NS_R, PT := PT_RED);
        TWR(IN := EW_R, PT := PT_ALLRED);

    5: // All-red clearance
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        TNS_G(IN := NS_G, PT := PT_ALLRED);
        TEW_G(IN := EW_G, PT := PT_ALLRED);
        TNR(IN := NS_R, PT := PT_ALLRED);
        TWR(IN := EW_R, PT := PT_ALLRED);
END_CASE

// Ensure no simultaneous green/yellow for both directions
IF NS_G AND EW_G THEN
    NS_G := FALSE;
    EW_G := FALSE;
ELSIF NS_Y AND EW_Y THEN
    NS_Y := FALSE;
    EW_Y := FALSE;
END_IF

