        IF DoorClosed AND NOT AtTop THEN
            MotorUp := TRUE;
            MotorDown := FALSE;
        ELSIF AtTop OR NOT DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
            State := 2;
        END_IF;
    2: // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
        END_IF;
    3: // Moving-down
        IF DoorClosed AND NOT AtBottom THEN
            MotorUp := FALSE;
            MotorDown := TRUE;
        ELSIF AtBottom OR NOT DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
            State := 0;
        END_IF;
END_CASE;

// Reset timers when motor is stopped
IF NOT MotorUp AND NOT MotorDown THEN
    UpTimer(IN := FALSE);
    DownTimer(IN := FALSE);
END_IF;

// Start timers when motor is started
IF MotorUp THEN
    UpTimer(IN := TRUE, PT := T#5s);
END_IF;
IF MotorDown THEN
    DownTimer(IN := TRUE, PT := T#5s);
END_IF;

// Ensure motor safety
MotorUp := MotorUp AND DoorClosed;
MotorDown := MotorDown AND DoorClosed;
END_PROGRAM

