            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;
        UpRequest := CallUp;
        DownRequest := CallDown;

    2: -- At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
            MotorUp := FALSE;
            MotorDown := TRUE;
        END_IF;
        UpRequest := FALSE;
        DownRequest := CallDown;

    3: -- Moving-down
        IF Not DoorClosed OR AtBottom THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        ELSIF CallUp AND DoorClosed THEN
            State := 1;
            MotorUp := TRUE;
            MotorDown := FALSE;
        ELSEIF AtBottom THEN
            State := 0;
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;
        UpRequest := CallUp;
        DownRequest := CallDown;
END_CASE

MotorUp := MotorUp AND DoorClosed AND Not MotorDown;
MotorDown := MotorDown AND DoorClosed AND Not MotorUp;

