VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    TFill : TON;
    TReact : TON;
END_VAR

IF NOT EStop THEN
    State := 0; -- Reset to Idle if EStop is activated
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSE
    CASE State OF
        0: -- Idle
            IF StartBatch AND Level >= LIQ_MIN THEN
                State := 1;
                TFill(IN := TRUE, PT := T#5m); -- Assume fill takes 5 minutes
            END_IF;

        1: -- Fill
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;

            IF TFill.Q OR Level >= LVL_HIGH THEN
                State := 2;
                TFill(IN := FALSE);
            END_IF;

        2: -- Heat
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;

            IF Temp >= TEMP_SET THEN
                State := 3;
                TReact(IN := TRUE, PT := PT_REACT);
            END_IF;

        3: -- React
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;

            IF NOT TReact.Q THEN
                State := 4;
                TReact(IN := FALSE);
            END_IF;

        4: -- Drain
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;

            IF Level <= LVL_LOW THEN
                State := 0;
                DrainValve := FALSE;
            END_IF;
    END_CASE;
END_IF;

-- Safety conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF NOT (State = 1 AND Level >= LIQ_MIN) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

END_PROGRAM

