                State := 3;
                Heater := FALSE;
                Agitator := FALSE;
            END_IF;

        3: -- React
            Heater := TRUE;
            Agitator := TRUE;
            ReactTimer(IN := TRUE, PT := PT_REACT);
            IF NOT ReactTimer.Q THEN
                State := 4;
                Heater := FALSE;
                Agitator := FALSE;
            END_IF;

        4: -- Drain
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
                DrainValve := FALSE;
            END_IF;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSE
    CASE State OF
        0 : -- Idle
            IF StartBatch AND Level >= LIQ_MIN THEN
                State := 1;
            END_IF;

        1 : -- Fill
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;

            IF Level >= LVL_HIGH THEN
                FillValve := FALSE;
                State := 2;
            END_IF;

        2 : -- Heat
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;

            IF Temp >= TEMP_SET THEN
                State := 3;
            END_IF;

        3 : -- React
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;

            IF DrainTimer.Q THEN
                State := 4;
            ELSE
                DrainTimer(IN := TRUE, PT := PT_REACT);
            END_IF;

        4 : -- Drain
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;

            IF Level <= LVL_LOW THEN
                DrainValve := FALSE;
                State := 0;
            END_IF;
    END_CASE;
END_IF;

END_PROGRAM

