    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

VAR_CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

Fan := FALSE;
Fuel := FALSE;
Ignition := FALSE;

CASE State OF
    0: // Off
        IF StartPB AND EStop THEN
            State := 1;
            PurgeTimer(IN := TRUE, PT := PT_PURGE);
        END_IF;

    1: // Pre-purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;

        IF NOT PurgeTimer.Q THEN
            State := 2;
            IgnitionTimer(IN := TRUE, PT := PT_IGN);
        END_IF;

    2: // Ignition trial
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;

        IF NOT IgnitionTimer.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;

        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

