PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    DemandTimer : TON;
END_VAR

// Detect falling edge of Demand
PrevDemand := Demand;

IF NOT EStop THEN
    // Emergency stop activates, stop all pumps
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    // Normal operation
    IF Demand AND NOT PrevDemand THEN
        // Demand starts, toggle Lead
        Lead := 1 - Lead;
    END_IF;

    IF Demand THEN
        // Demand active, activate appropriate pump
        Pump1 := (Lead = 0);
        Pump2 := (Lead = 1);
    ELSE
        // Demand ends, deactivate both pumps
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_IF;
END_IF;

END_PROGRAM

