    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    PumpTimer : TON;
END_VAR

PumpTimer(IN := NOT(EStop) AND Demand, PT := T#0s);

PrevDemand := Demand;

IF NOT(EStop) THEN
    IF Demand THEN
        CASE Lead OF
            0: 
                Pump1 := TRUE;
                Pump2 := FALSE;
            1: 
                Pump1 := FALSE;
                Pump2 := TRUE;
        END_CASE;
    ELSE
        Lead := 1 - Lead;
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_IF;
ELSE
    Pump1 := FALSE;
    Pump2 := FALSE;
END_IF;

Lead := Lead MOD 2; // Ensure Lead remains within the valid range [0, 1]
END_PROGRAM

