    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    T1 : TON;
END_VAR

Pump1 := FALSE;
Pump2 := FALSE;

T1(IN := NOT EStop AND Demand, PT := T#0s);

IF EStop THEN
    Lead := 0;
    PrevDemand := FALSE;
    T1(IN := FALSE, PT := T#0s);
END_IF;

IF NOT EStop THEN
    IF Demand AND NOT PrevDemand THEN
        Lead := 1 - Lead;
    END_IF;

    PrevDemand := Demand;

    IF Lead = 0 THEN
        Pump1 := Demand;
        Pump2 := NOT Demand;
